export function trieOperations(operations: string[][]): (boolean | null)[] {
  type TrieNode={children:Map<string,TrieNode>; terminal:boolean}; const root: TrieNode={children:new Map(),terminal:false}; const result:(boolean|null)[]=[]; for(const [operation,text] of operations) { let node:TrieNode|undefined=root; for(const c of text) { if(operation==='insert'&&!node.children.has(c)) node.children.set(c,{children:new Map(),terminal:false}); node=node.children.get(c); if(!node) break; } if(operation==='insert') { node!.terminal=true; result.push(null); } else result.push(operation==='search'?!!node?.terminal:node!==undefined); } return result;
}
